            "expected": "Distinct named human cleanup and recovery assignees acknowledge ownership and coverage before cutover.",
            "gate_id": "G-D-OWNERS"
          },
          {
            "check": "Snapshot and digest the pre-D state, perform a D rollback drill, then run conformance and recovery smoke tests against the restored state.",
            "expected": "The pre-D digest is preserved, restoration succeeds, and all smoke tests pass.",
            "gate_id": "G-D-ROLLBACK"
          }
        ],
        "option": "D",
        "owner": "Migration lead; a named human assignee is required before phase 1 starts",
        "phase": 1,
        "purpose": "Provide the legacy-compatible bridge within 14 days while preserving the pre-D state and collecting recovery evidence.",
        "rollback_triggers": [
          {
            "action": "Stop D promotion, retain or restore the preserved legacy state, and replan the bridge without starting B promotion.",
            "check": "Evaluate elapsed time, completion forecast, and legacy conformance after every rehearsal and deployment checkpoint.",
            "condition": "Any required legacy case fails or the forecast or elapsed duration exceeds 14 days.",
            "trigger_id": "RT-D-MIGRATION"
          },
          {
            "action": "Halt D cutover and restore the preserved pre-D state until ownership, objective, and a passing drill are recorded.",
            "check": "Page the recovery owner and execute the documented recovery drill before cutover and after any recovery-path change.",
            "condition": "No named owner acknowledges, escalation coverage is absent, or recovery fails or exceeds its predeclared objective.",
            "trigger_id": "RT-D-RECOVERY"
          },
          {
            "action": "Freeze all migration writes and recover the last verified pre-D snapshot before another cutover attempt.",
            "check": "Verify the pre-D snapshot digest and restoration smoke tests after every D state mutation.",
            "condition": "The prior-state digest differs, restoration is unavailable, or a restoration smoke test fails.",
            "trigger_id": "RT-D-STATE"
          }
        ]
      },
      {
        "gates": [
          {
            "check": "In the declared provider/runtime, attempt mounts outside the workspace and credential use outside the assigned run, workspace, and lifetime; then revoke credentials and retry.",
            "expected": "All out-of-workspace mounts and out-of-scope or revoked credential uses are denied and logged.",
            "gate_id": "G-B-ISOLATION"
          },
          {
            "check": "Rerun B warm and cold benchmarks separately under one recorded provider identity and window using a prespecified sample and censoring protocol.",
            "expected": "Both valid separate distributions meet the predeclared service objective; all samples, censoring, and exclusions are recorded and no pooled result is used.",
            "gate_id": "G-B-PERFORMANCE"
          },
          {
            "check": "Page named operations, cleanup, recovery, credential, and isolation assignees and execute the B incident-escalation and recovery drill.",
            "expected": "Every assignee acknowledges coverage and the drill meets the predeclared recovery objective.",
            "gate_id": "G-B-OPERATIONS"
          },
          {
            "check": "Preserve and digest the D state, execute a B-to-D rollback drill, and run legacy conformance plus recovery smoke tests.",
            "expected": "The D digest is preserved, B-to-D restoration succeeds, and all smoke tests pass.",
            "gate_id": "G-B-ROLLBACK"
          }
        ],
        "option": "B",
        "owner": "Execution-platform operations lead; a named human assignee is required before phase 2 promotion",
        "phase": 2,
        "purpose": "Promote B as the isolation-led target only after current provider-specific evidence and operational controls pass, while D remains recoverable.",
        "rollback_triggers": [
          {
            "action": "Revoke affected credentials, stop new B executions, preserve incident evidence, and restore D.",
            "check": "Continuously audit mount denials, credential scope and revocation events, and workspace-boundary tests.",
            "condition": "Any mount escapes the workspace, any credential works beyond its declared scope or lifetime, or a required denial is not logged.",
            "trigger_id": "RT-B-ISOLATION"
          },
          {
            "action": "Stop B promotion or new B traffic, retain D, and rerun the workload-specific study before reconsideration.",
            "check": "Evaluate separate warm and cold service-objective results and censoring at every rollout checkpoint.",
            "condition": "Either workload misses its predeclared objective, censoring is unexplained, or warm and cold observations are pooled.",
            "trigger_id": "RT-B-PERFORMANCE"
          },
          {
            "action": "Halt B traffic, invoke the incident plan, and restore D until ownership and recovery evidence are current.",
            "check": "Page accountable assignees and run the recovery drill on schedule and after recovery-path or owner changes.",
            "condition": "An accountable owner is absent or unreachable, escalation coverage lapses, or recovery misses its predeclared objective.",
            "trigger_id": "RT-B-RECOVERY"
          },
          {
            "action": "Freeze B state changes and restore the last verified D snapshot.",
            "check": "Verify the preserved D digest and B-to-D restoration smoke tests at every rollout checkpoint.",
            "condition": "The D state is not preserved, its digest differs, or a rollback smoke test fails.",
            "trigger_id": "RT-B-STATE"
          }
        ]
      }
    ],
    "strategy": "Stage D as a time-bounded legacy-compatible migration bridge, then promote B as the target only after isolation, ownership, workload-separated performance, recovery, and rollback gates pass; preserve D until B rollback risk closes."
